-- 17_place_area.sql — ④ 신예지 (여행 중 도착 판정). 이상재(DB 총괄) 확인 필요. 각자 \i 'db/17_place_area.sql' 실행
--  넓은 장소는 대표 점 하나 + 150m로는 도착이 안 잡혀서, 경계(폴리곤)가 있는 장소는 경계로 판정해요
--  경계 30m 안 = 도착, 80m 밖 = 출발. 경계 없는 장소는 지금처럼 점 + 150m/200m
--  다시 실행해도 안전하게 (IF NOT EXISTS, ON CONFLICT DO NOTHING)

-- ---------------------------------------------------------------- place_area · 넓은 장소 경계
--  칸(trip_stop)과는 place_id가 같거나 이름이 같을 때만(띄어쓰기 무시) 이어요
--  좌표로만 이으면 안 됨: 여의도샛강생태공원도 여의도한강공원 경계 안에 들어가요
CREATE TABLE IF NOT EXISTS place_area (
  area_id    BIGSERIAL    PRIMARY KEY,
  place_id   TEXT         REFERENCES retrip_place(id) ON DELETE SET NULL,  -- DB에 없는 장소면 NULL
  name       VARCHAR(60)  NOT NULL UNIQUE,                                 -- 칸 이름과 맞춰볼 이름
  source     VARCHAR(40)  NOT NULL,                                        -- 어디서 가져왔는지 (예: osm:relation/7550666)
  boundary   geography(MultiPolygon, 4326) NOT NULL,                       -- 경계 (경도 위도 순서)
  created_at TIMESTAMP    NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_place_area_boundary ON place_area USING GIST (boundary);

